    // 예약이 걸려 있으면 맨 앞 예약자만 빌릴 수 있고, 빌리는 순간 그 예약은 소진된다.
    // 신용조회에서 거절된 회원은 빌릴 수 없으며, 이때 책과 예약 상태는 바뀌지 않는다.
    public Loan loanTo(Member member, int activeLoanCount, LocalDate today, ReservationQueue reservations,
                       CreditCheck creditCheck) {
        ensureSameBook(reservations);
        Objects.requireNonNull(creditCheck, "creditCheck").ensureApproved(member.getId());
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        reservations.ensureMayBorrow(member.getId());
        member.ensureCanBorrow(activeLoanCount);
        reservations.fulfillFor(member.getId());
        status = BookStatus.ON_LOAN;
        return Loan.start(id, member.getId(), today, creditCheck);
    }

    // 예약은 지금 빌릴 수 없는 책에만 걸 수 있다. 대출 중이거나, 반납됐어도 앞선 예약자를 기다리는 책이다.
    public Reservation reserveFor(Member member, ReservationQueue reservations) {
package com.example.lending.application.port.out;

