        member.ensureNotSuspended();
        CreditCheck creditCheck = creditCheckPort.check(member);
        ReservationQueue reservations = loadReservationPort.loadReservationQueue(book.getId());
        Loan loan = book.loanTo(member, loadLoanPort.countActiveLoans(member.getId()),
                command.loanedAt() != null ? command.loanedAt() : LocalDate.now(), reservations, creditCheck);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveReservationPort.saveReservationQueue(reservations);
        return loan;
    }
}

